package com.yihe.framework.ehr;
import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;
/** Scoped views of existing work; no autonomous clinical or notification actions. */
@Service @SuppressWarnings("unchecked")public class AgentWorkspaceService {
 final EhrRepository db;final EhrService ehr;final AgentOverviewService overview;final DigitalWorkerTaskService tasks;
 public AgentWorkspaceService(EhrRepository db,EhrService ehr,AgentOverviewService overview,DigitalWorkerTaskService tasks){this.db=db;this.ehr=ehr;this.overview=overview;this.tasks=tasks;}
 Map<String,Object>counts(String from,String where,List<Object>args){Map<String,Object>m=overview.empty();for(Map<String,Object>r:db.all("SELECT status,COUNT(*) n FROM "+from+where+" GROUP BY status",args.toArray())){long n=((Number)r.get("n")).longValue();m.put(r.get("status").toString(),n);m.put("total",((Number)m.get("total")).longValue()+n);}return m;}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)public Map<String,Object>workspace(EhrActor a,Map<String,String>q){overview.allow(a);String worker=q.getOrDefault("worker","");require(worker.isEmpty()||AgentOverviewService.WORKERS.contains(worker),422,"员工无效");int days=overview.positive(q.get("days"),7,90);require(Arrays.asList(7,30,90).contains(days),422,"趋势仅支持7、30或90天");List<Object>args=new ArrayList<>();String from=overview.from(a,args),where=" WHERE 1=1";if(!worker.isEmpty()){where+=" AND worker=?";args.add(worker);}String today=" AND createdAt>="+AgentOverviewService.today()+" AND createdAt<DATE_ADD("+AgentOverviewService.today()+",INTERVAL 1 DAY)",yesterday=" AND createdAt>=DATE_SUB("+AgentOverviewService.today()+",INTERVAL 1 DAY) AND createdAt<"+AgentOverviewService.today();List<Map<String,Object>>trend=db.all("SELECT "+AgentOverviewService.day()+" day,COUNT(*) total,SUM(status='completed') completed,SUM(status='failed') failed FROM "+from+where+" AND createdAt>=DATE_SUB("+AgentOverviewService.today()+",INTERVAL "+(days-1)+" DAY) AND createdAt<DATE_ADD("+AgentOverviewService.today()+",INTERVAL 1 DAY) GROUP BY "+AgentOverviewService.day()+" ORDER BY day",args.toArray());Map<String,Object>panels=new LinkedHashMap<>();for(String state:Arrays.asList("in_progress","completed","pending_review","failed")){List<Map<String,Object>>rows=db.all("SELECT * FROM "+from+where+(state.equals("in_progress")?"":today)+" AND status=? ORDER BY updatedAt DESC,source,id DESC LIMIT 5",join(args,state));for(Map<String,Object>r:rows)overview.decorate(a,r);panels.put(state,rows);}Map<String,Object>list=overview.list(a,q);for(Map<String,Object>r:(List<Map<String,Object>>)list.get("items"))metadata(a,r);return map("today",counts(from,where+today,args),"yesterday",counts(from,where+yesterday,args),"all",counts(from,where,args),"trend",trend,"distribution",db.all("SELECT type,source,worker,COUNT(*) count FROM "+from+where+today+" GROUP BY type,source,worker",args.toArray()),"panels",panels,"list",list,"tokenUsage",null,"automationRate",null,"capturedAt",now(),"worker",worker);}
 Object[]join(List<Object>args,Object value){List<Object>x=new ArrayList<>(args);x.add(value);return x.toArray();}
 void metadata(EhrActor a,Map<String,Object>row){String source=text(row,"source"),id=text(row,"id");row.put("riskLevel","unknown");row.put("riskConfirmed",false);if(num(row.get("canOpen"))==0)return;if(Arrays.asList("exam","chronic","occupational","psychological").contains(source)){String table=table(source);Map<String,Object>t=db.one("SELECT risk_level,review_state,created_at,finished_at FROM "+table+" WHERE task_id=? AND scope_code=? AND data_mode=?",id,a.scope,a.mode);if(t!=null){row.put("riskLevel",t.get("risk_level"));row.put("riskConfirmed","confirmed".equals(t.get("review_state")));row.put("finishedAt",t.get("finished_at"));}}}
 String table(String source){switch(source){case"exam":return"a_ai_exam_tasks";case"comprehensive":return"a_comprehensive_analyses";case"chronic":return"a_chronic_risk_tasks";case"occupational":return"a_occupational_risk_tasks";case"psychological":return"a_psych_assessment_tasks";default:throw new EhrException(422,"任务来源无效");}}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)public Map<String,Object>detail(EhrActor a,String source,String id){overview.allow(a);require(AgentOverviewService.SOURCES.contains(source)&&id.length()<=100,422,"任务标识无效");List<Object>args=new ArrayList<>();String from=overview.from(a,args);args.add(source);args.add(id);Map<String,Object>row=db.one("SELECT * FROM "+from+" WHERE source=? AND id=?",args.toArray());require(row!=null,404,"任务不存在或无权访问");overview.decorate(a,row);if(!text(row,"recordId").isEmpty()&&db.count("SELECT COUNT(*) FROM a_health_records r JOIN a_employee_roster_profiles p ON p.employee_id=r.employee_id AND p.scope_code=r.scope_code AND p.data_mode=r.data_mode WHERE r.record_id=? AND r.scope_code=? AND r.data_mode=? AND p.deleted_at IS NULL",row.get("recordId"),a.scope,a.mode)==0){row.put("canOpen",0);row.put("href",null);}metadata(a,row);Map<String,Object>result=map("task",row,"events",Collections.emptyList(),"output",null,"errorCode",null,"tokenUsage",null,"toolCallsAvailable",false);if(num(row.get("canOpen"))==0){result.put("unavailable",true);return result;}
 if(source.equals("assignment")){Map<String,Object>task=tasks.detail(a,id),ai=(Map<String,Object>)task.get("ai");result.put("events",task.get("events"));result.put("assignment",task);result.put("output",ai==null?task.get("resultNote"):ai.get("output"));result.put("errorCode",ai==null?null:ai.get("errorCode"));result.put("version",task.get("version"));result.put("instructions",task.get("instructions"));result.put("taskContext",task.get("taskContext"));if(ai!=null)result.put("aiState",ai.get("state"));}
 else if(source.equals("psych_workflow")){Map<String,Object>t=db.one("SELECT result_json FROM a_psych_worker_items WHERE item_id=? AND scope_code=? AND data_mode=?",id,a.scope,a.mode);result.put("output",t.get("result_json"));result.put("events",db.all("SELECT action,actor,detail_json note,created_at time FROM a_psych_worker_events WHERE item_id=? AND scope_code=? AND data_mode=? ORDER BY created_at",id,a.scope,a.mode));}
 else if(source.equals("collaboration")){Map<String,Object>t=db.one("SELECT order_state,result_json FROM a_worker_orders WHERE order_id=? AND scope_code=? AND data_mode=?",id,a.scope,a.mode);result.put("output",t.get("result_json"));result.put("events",db.all("SELECT action,actor,detail_json note,created_at time FROM a_worker_order_events WHERE order_id=? AND scope_code=? AND data_mode=? ORDER BY created_at",id,a.scope,a.mode));}
 else if(source.equals("ocr")){Map<String,Object>t=db.one("SELECT last_error_code errorCode,last_error_message errorMessage,progress_stage stage,progress_percent percent,attempt_count attempts,created_at createdAt,updated_at updatedAt FROM a_ocr_dispatch_tasks WHERE job_id=? AND scope_code=? AND data_mode=?",id,a.scope,a.mode);result.put("ocr",t);result.put("errorCode",t.get("errorCode"));result.put("events",db.all("SELECT outcome action,worker_id actor,progress_stage stage,progress_percent percent,started_at time,finished_at finishedAt,error_code errorCode,error_message note FROM a_ocr_dispatch_attempts WHERE job_id=? AND data_mode=? ORDER BY attempt_number",id,a.mode));}
 else if(!source.equals("alert")){boolean comp=source.equals("comprehensive");String table=table(source),key=comp?"analysis_id":"task_id";Map<String,Object>t=db.one("SELECT "+(source.equals("exam")?"result_text":"output_text")+" output,error_code errorCode,created_at createdAt,finished_at finishedAt,row_version version"+(comp?"":",review_state reviewState,reviewed_at reviewedAt,reviewer,review_note reviewNote")+" FROM "+table+" WHERE "+key+"=? AND scope_code=? AND data_mode=?",id,a.scope,a.mode);result.put("output",t.get("output"));result.put("errorCode",t.get("errorCode"));result.put("execution",t);if(comp)result.put("events",db.all("SELECT 'reviewed' action,reviewer actor,created_at time FROM a_comprehensive_reviews WHERE analysis_id=? AND scope_code=? AND data_mode=? ORDER BY created_at",id,a.scope,a.mode));else result.put("events",db.all("SELECT action,actor,note,created_at time FROM "+(source.equals("exam")?"a_ai_exam_events":source.equals("chronic")?"a_chronic_risk_events":source.equals("occupational")?"a_occupational_risk_events":"a_psych_assessment_events")+" WHERE task_id=? ORDER BY created_at,event_id",id));}
 return result;}
}
